package communication;import cern.accsoft.commons.util.value.Pair;import cern.cmw.data.Data;import cern.cmw.data.Entry;import codec.ByteStreamDecoder;import codec.javatocmw.CMWDataEncoder;import codec.lvtojava.LVDataDeserialiser;import codec.lvtojava.LVTypeDecoderImp;import jakarta.servlet.ServletInputStream;import jakarta.servlet.http.HttpServlet;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import types.JavaDataContainer;import types.labview.LVTypeDescriptor;import java.io.IOException;import java.util.List;public class HTTPListener extends HttpServlet {        /**         * @param args         */        public static void main(String[] args) {        }        public void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {            ServletInputStream reader = request.getInputStream();            byte[] message = reader.readAllBytes();            ByteStreamDecoder byteStreamDecoder = new ByteStreamDecoder();            JavaDataContainer javaDataContainer = byteStreamDecoder.decode(message);            Data data = CMWDataEncoder.encode(javaDataContainer);            System.out.println(data);        }}